style.css:
@-moz-document domain("i-ready.com") {
body {
        /* Add your image URL here */
        background: url(https://wallpapercave.com/wp/wp6404604.jpg) no-repeat center center fixed;
        background-size: cover;

        /* Ensure text remains readable on the background */
        color: #ffffff; /* Adjust text color if needed */
    }

    /* Optional: Style other areas if needed */
    .content-container, .main-wrapper, .page-content {
        background: transparent !important; /* Make default boxes transparent */
    }

    /* Fix for interactive elements */
    input, select, textarea {
        background: rgba(255, 255, 255, 0.8) !important;
        color: #000 !important;
    }

    /* Adjust scrollbar style (optional) */
    ::-webkit-scrollbar {
        width: 8px;
    }

    ::-webkit-scrollbar-thumb {
        background-color: rgba(255, 255, 255, 0.5);
        border-radius: 4px;
    }

    ::-webkit-scrollbar-track {
        background-color: rgba(0, 0, 0, 0.3);
    }
}
